-- Hooks -----------------------------------------------------------------

--- Wraps a render function as a reusable component. `Counter { ... }` (calling the result) produces an
--- element — a lazy description expanded later once its path-based identity is known, which is what
--- makes hook state and hot reload work.
---@param nameOrFn string|(fun(props: table?): khoma.Element|khoma.Element[]|nil)
---@param fn (fun(props: table?): khoma.Element|khoma.Element[]|nil)?
---@return khoma.Component
function component(nameOrFn, fn) end

--- Component-local state, identity-keyed so it survives hot reload. The setter accepts either a new
--- value or an updater `function(prev) return next end`; updates are batched and coalesced into one
--- render.
---@generic T
---@param initial T
---@return T value
---@return fun(next: T|fun(prev: T): T) setter
function useState(initial) end

--- A stable mutable box that does not trigger re-renders when written.
---@generic T
---@param initial T
---@return { current: T } ref
function useRef(initial) end

--- Caches `fn()`'s result until `deps` changes (shallow compare: scalars by value, tables/functions by
--- reference).
---@generic T
---@param fn fun(): T
---@param deps table?
---@return T
function useMemo(fn, deps) end

--- Runs `fn` after the render pass commits, when `deps` changed (every render if `deps` is omitted,
--- once if `deps` is `{}`). `fn` may return a cleanup function, run before the next execution and on
--- unmount.
---@param fn fun(): (fun()|nil)
---@param deps table?
function useEffect(fn, deps) end

--- Calls `fn` every `ms` milliseconds; cancelled automatically on unmount. `fn` is re-bound every
--- render, so it never closes over stale state.
---@param fn fun()
---@param ms number
function useInterval(fn, ms) end

--- Calls `fn` once after `ms` milliseconds; cancelled automatically on unmount if it hasn't fired yet.
---@param fn fun()
---@param ms number
function useTimeout(fn, ms) end

--- Subscribes to a Go-backed store (a khoma.Store global such as `Battery` or `Screens`) and re-renders
--- when it changes. An optional selector narrows re-renders to when the *selected* value changes.
---@generic T
---@param store khoma.Store
---@param selector (fun(value: any): T)?
---@return T
function useStore(store, selector) end

--- A Lua-granularity animated number: when `target` changes, the returned value tweens toward it at the
--- configured fps, re-rendering the component each tick. For per-frame animation with zero Lua work,
--- use the `animate` widget prop instead.
---@param target number
---@param opts { duration: number?, easing: string?, fps: number? }?
---@return number
function useAnimatedValue(target, opts) end

--- Like useState, but the initial value is read from (and every update written to) a JSON file on disk
--- keyed by AppID, so it survives process restart. `key` is a plain string the caller picks — two
--- instances sharing a key intentionally share state, same contract as browser localStorage.
---@generic T
---@param key string
---@param initial T
---@return T value
---@return fun(next: T|fun(prev: T): T) setter
function usePersistent(key, initial) end

